{
  "avaliacoes": [
    {
      "id": "E88336dae3940a31d",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "O estudo descreve uma metodologia que combina análise numérica, critérios operacionais e estudos preliminares de risco para avaliar e reduzir indisponibilidade operacional em operações de alívio com navios aliviadores em FPSO.",
          "trechos": [
            "E88336dae3940a31d:0:698",
            "E88336dae3940a31d:1395:2094"
          ],
          "condicoes": [
            "Aplicado a operações de offloading com navios aliviadores com posicionamento dinâmico",
            "Cenários frequentes nas Bacias de Campos e Santos"
          ],
          "limites": [
            "Trata-se de estudo teórico descrito no documento",
            "O trecho não apresenta limites numéricos operacionais nem critérios diretamente voltados a dispersão de gases, fumaça ou flare"
          ]
        },
        {
          "proposicao": "A representação das condições ambientais do estudo utiliza doze anos de dados simultâneos de ventos, ondas bidirecionais e correntes, mostrando uso de base meteoceanográfica para análise de disponibilidade operacional.",
          "trechos": [
            "E88336dae3940a31d:0:698",
            "E88336dae3940a31d:1395:2094"
          ],
          "condicoes": [
            "Modelagem das regiões analisadas por dados do projeto METOCEAN"
          ],
          "limites": [
            "O trecho não informa resolução temporal, critérios estatísticos nem envelopes ambientais finais"
          ]
        },
        {
          "proposicao": "Os resultados das análises estáticas permitem excluir casos em que a operação de alívio seria interrompida pela incapacidade do navio de manter posição dentro dos setores operacionais, e o estudo propõe novos setores e estratégias de posicionamento.",
          "trechos": [
            "E88336dae3940a31d:698:1395",
            "E88336dae3940a31d:2094:2498"
          ],
          "condicoes": [
            "Dependente do desempenho de manutenção de posição do navio aliviador",
            "Aplicável aos setores operacionais considerados no estudo"
          ],
          "limites": [
            "O excerto não detalha critérios de aceitação de posição nem como as propostas foram validadas em campo"
          ]
        }
      ]
    },
    {
      "id": "E9ae2641d9f13d823",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A perda de posição de uma instalação flutuante é tratada como perigo com potencial de acidente maior e deve ser avaliada no safety case, inclusive pelo risco de colisão com instalação adjacente ou liberação de hidrocarbonetos por fratura de risers de perfuração ou de poço.",
          "trechos": [
            "E9ae2641d9f13d823:0:699"
          ],
          "condicoes": [
            "No contexto regulatório e de orientação do HSE do Reino Unido para instalações flutuantes"
          ],
          "limites": [
            "Norma e orientação estrangeiras; não constituem por si sós requisito brasileiro universal",
            "O trecho não aborda especificamente dispersão de gases, fumaça ou flare"
          ]
        },
        {
          "proposicao": "O documento afirma expectativa de que o sistema de amarração seja projetado, construído, operado e mantido segundo padrões reconhecidos para atender às condições meteoceanográficas da área de operação.",
          "trechos": [
            "E9ae2641d9f13d823:699:1397"
          ],
          "condicoes": [
            "Aplicável ao projeto e gestão do sistema de amarração",
            "Considerando as condições meteoceanográficas prevalentes na área"
          ],
          "limites": [
            "Expressa expectativa regulatória do HSE e referência a normas reconhecidas da indústria",
            "O trecho não traz critérios quantitativos de projeto"
          ]
        },
        {
          "proposicao": "O tipo de amarração do FPSO influencia o comportamento operacional, distinguindo sistemas totalmente weather-vaning, sistemas com controle de aproamento por thrusters e sistemas assistidos por thrusters para limitar tensões de amarração sob o tempo prevalente.",
          "trechos": [
            "E9ae2641d9f13d823:1397:2091"
          ],
          "condicoes": [
            "Conforme o tipo particular de amarração adotado"
          ],
          "limites": [
            "O trecho não compara desempenho entre arranjos nem define critérios de seleção entre eles"
          ]
        }
      ]
    },
    {
      "id": "E366e429d41359985",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Para projeto e conversão de FPSOs/FSUs, o documento indica uso de dados meteoceanográficos específicos do local, considerando incertezas na previsão de extremos de longo prazo, e revisão/validação desses dados em avaliações de extensão de vida de instalações existentes.",
          "trechos": [
            "E366e429d41359985:0:695",
            "E366e429d41359985:695:1395"
          ],
          "condicoes": [
            "No contexto de orientação do HSE do Reino Unido para projeto/conversão e life extension"
          ],
          "limites": [
            "Norma/orientação estrangeira; não constitui requisito brasileiro universal",
            "O trecho não fornece método detalhado para tratar as incertezas"
          ]
        },
        {
          "proposicao": "A operação prolongada sem docagem introduz desafios de integridade e manutenção, incluindo necessidade potencial de mais manutenção, aumento de pessoal a bordo e impactos correlatos em arranjos de acomodação, evacuação, fuga e meios de salvamento.",
          "trechos": [
            "E366e429d41359985:695:1395"
          ],
          "condicoes": [
            "Instalações flutuantes em operação de longo prazo em locação permanente sem drydocking"
          ],
          "limites": [
            "O trecho não quantifica aumento de efetivo nem capacidade adicional necessária"
          ]
        },
        {
          "proposicao": "O projeto deve considerar inspeção e manutenção em condições severas offshore e, quando não houver docagem planejada durante a campanha, deve contemplar inspeção em substituição à docagem e integridade suficiente para componentes sem possibilidade de inspeção.",
          "trechos": [
            "E366e429d41359985:1395:2089"
          ],
          "condicoes": [
            "Harsh weather conditions offshore",
            "Quando não houver previsão de drydocking durante o período de operação"
          ],
          "limites": [
            "O trecho não detalha técnicas de inspeção nem critérios de aceitabilidade estrutural"
          ]
        }
      ]
    },
    {
      "id": "Ef12966a37f7eb3a9",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O documento trata o safety case como documento vivo, a ser atualizado quando houver mudanças na estrutura, equipamentos ou processos descritos, e parte dessas mudanças pode requerer avaliação formal e aceitação pelo regulador citado.",
          "trechos": [
            "Ef12966a37f7eb3a9:1395:2091"
          ],
          "condicoes": [
            "No contexto regulatório do Reino Unido"
          ],
          "limites": [
            "Norma/orientação estrangeira; não constitui requisito brasileiro universal",
            "O trecho não define critérios objetivos para classificar materialidade da mudança"
          ]
        },
        {
          "proposicao": "Os arranjos de gestão de integridade, incluindo esquemas de inspeção e suas mudanças, devem passar por processo de verificação, e devem existir revisões periódicas da integridade por pessoas competentes.",
          "trechos": [
            "Ef12966a37f7eb3a9:0:697"
          ],
          "condicoes": [
            "No contexto de gestão de integridade de instalações flutuantes"
          ],
          "limites": [
            "O trecho não especifica periodicidade nem metodologia de verificação"
          ]
        },
        {
          "proposicao": "A revisão aprofundada do safety case deve considerar integridade associada ao envelhecimento e ao fim de vida, com a finalidade de confirmar que o safety case permanece fundamentalmente consistente.",
          "trechos": [
            "Ef12966a37f7eb3a9:697:1395"
          ],
          "condicoes": [
            "Ao longo da vida operacional da instalação"
          ],
          "limites": [
            "O trecho não detalha indicadores técnicos para essa confirmação"
          ]
        }
      ]
    },
    {
      "id": "E66b85f739dd153e7",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "No caso investigado, o procedimento de gestão de mudanças vigente não contemplava mudanças em procedimentos, apenas mudanças na unidade, equipamentos, sistemas e pessoas.",
          "trechos": [
            "E66b85f739dd153e7:0:700"
          ],
          "condicoes": [
            "Situação observada no dia do acidente no FPSO Cidade de São Mateus"
          ],
          "limites": [
            "Achado restrito ao caso investigado",
            "O trecho não demonstra, por si só, efeito específico sobre contingências ambientais, vento, gases ou fumaça"
          ]
        },
        {
          "proposicao": "Também no caso investigado, não havia definição de procedimentos críticos para a unidade em razão da não conclusão da migração de procedimentos, apesar de auditoria interna prévia ter apontado necessidade de atualização.",
          "trechos": [
            "E66b85f739dd153e7:0:700",
            "E66b85f739dd153e7:700:1397"
          ],
          "condicoes": [
            "Contexto de revisão e atualização de procedimentos operacionais da unidade"
          ],
          "limites": [
            "Achado específico do FPSO investigado",
            "O excerto não liga diretamente essa lacuna a desempenho meteoceanográfico, SIMOPS ou flare"
          ]
        },
        {
          "proposicao": "O relatório relata diversas mudanças em procedimentos do sistema de gestão readequados aos requisitos da BW, com interferência no gerenciamento de segurança operacional, e registra que a alteração de operador da instalação só foi oficializada à ANP anos após o início das mudanças.",
          "trechos": [
            "E66b85f739dd153e7:1397:2096"
          ],
          "condicoes": [
            "No processo de transição de gestão da instalação investigada"
          ],
          "limites": [
            "Achado de investigação, não regra geral",
            "O trecho não detalha efeitos específicos sobre prontidão operacional ou resposta a mudanças rápidas de condições ambientais"
          ]
        }
      ]
    },
    {
      "id": "Ea305d5d9b23def47",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O procedimento citado relaciona a necessidade de revisão do Safety Case a novos conhecimentos, incidentes, mudanças em padrões de segurança, fatores humanos e alterações de projeto e parâmetros operacionais, incluindo como exemplo a vida útil afetada por fadiga e corrosão de topside e casco.",
          "trechos": [
            "Ea305d5d9b23def47:0:700"
          ],
          "condicoes": [
            "No contexto do procedimento da BW mencionado no relatório"
          ],
          "limites": [
            "Refere-se ao procedimento e ao caso descritos no relatório",
            "O trecho não apresenta critério quantitativo para disparar a revisão"
          ]
        },
        {
          "proposicao": "Para determinar se a revisão do Safety Case seria requerida, o procedimento mencionava a realização de estudos de HAZID e HAZOP baseados nas áreas de mudança identificadas, com documentação da decisão de revisar ou não.",
          "trechos": [
            "Ea305d5d9b23def47:700:1398"
          ],
          "condicoes": [
            "Quando existirem áreas de mudança identificadas"
          ],
          "limites": [
            "O trecho não informa o conteúdo nem os resultados desses estudos"
          ]
        },
        {
          "proposicao": "O relatório registra referência a entendimento de que análises de risco precisam ser reavaliadas quando houver desvio das bases de análise ou quando surgirem situações novas significativas ou mudanças significativas na instalação.",
          "trechos": [
            "Ea305d5d9b23def47:1398:2097"
          ],
          "condicoes": [
            "Se houver desvio em relação a método, modelos, dados de entrada, premissas ou limitações da análise",
            "Se forem identificadas novas situações significativas ou mudanças significativas"
          ],
          "limites": [
            "O trecho reproduz referências normativas e orientativas citadas no relatório; não constitui por si só requisito brasileiro universal",
            "Não especifica critérios objetivos de significância"
          ]
        }
      ]
    }
  ],
